from cosmo_wap.lib.utils import add_empty_methods_pk

"""
So pass fNL as kwarg - also for forecasts of different types of fnl then pass
specific fNL_loc,fNL_eq instead.
"""

# their multipoles, mu and l come from pk/Pk_PP.py (generated by mathwap) - see pk.combined


@add_empty_methods_pk('l1','l3')
class Loc:
    """local: scale-dependent bias b_01/M(k)"""


@add_empty_methods_pk('l1','l3')
class Eq:
    """equilateral: k^2 b_01/M(k)"""


@add_empty_methods_pk('l1','l3')
class Orth:
    """k^2, as Eq: the orthogonal-LSS template goes as (k_L/k_S)^2 when squeezed - see cosmo_wap.lib.orth_lss"""
